import json,pathlib
D=pathlib.Path(__file__).parent
J=[]
def add(pid,cs,rs,note=''):
 c=[]
 for row in cs:
  n,reason,*err=row
  c.append(dict(candidate_id=f'CiTE-{n:04}',label=err[0] if err else 'supported',error_tags=err[1] if len(err)>1 else ['none'],reason=reason))
 r=[]
 for i,row in enumerate(rs,1):
  reason,full,*extra=row
  z=dict(reference_id=f'G{pid}-{i:03}',label='valid',reason=reason,full_coverage_sets=[[f'CiTE-{n:04}' for n in s] for s in full],partial_candidates=[f'CiTE-{n:04}' for n in extra[0]] if extra else [])
  if len(extra)>1:z['label']=extra[1];z.pop('full_coverage_sets')
  r.append(z)
 J.append(dict(paper_id=pid,candidates=c,references=r,note=note))
def save():
 (D/'judgments.json').write_text(json.dumps(J,ensure_ascii=False,indent=2))
